package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import java.math.*;
/** Displayed decimal precision is part of the question, including zero and trailing zeros. */
public final class DecimalToFractionSupply {
 private DecimalToFractionSupply(){}
 public static final String ID="el_decimal_fraction";
 public static boolean selected(String id,CurriculumLimits limits){return ID.equals(id)&&limits.variedFacts();}
 public static String read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(\\d{1,9}\\.\\d{1,9})의 값을 분수로 나타내세요\\.").matcher(q.prompt);return m.matches()?m.group(1):null;}
 public static Question make(int whole,int fractional,int places){if(whole<0||whole>99||places<1||places>3||fractional<0||fractional>=Math.pow(10,places))throw new IllegalArgumentException("Selected decimal fraction scope");int denominator=(int)Math.pow(10,places),numerator=whole*denominator+fractional;String raw=whole+"."+String.format(Locale.ROOT,"%0"+places+"d",fractional);Question q=new Question(ID,raw+"의 값을 분수로 나타내세요.",raw,Rational.of(numerator,denominator).toString());q.stepSupport=false;q.answerFormat="fraction";DecimalFractionRelations.attach(q);return q.withInputs(Rational.of(numerator,denominator));}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int maxPlaces=Math.min(3,limits.decimalPlaces(2)),minimum=limits.givenMinimum(0),maximum=limits.givenMaximum(99),places=1+random.nextInt(maxPlaces),scale=(int)Math.pow(10,places),count=(maximum-minimum+1)*scale;return IndexedQuestionSupply.choose(count,index->make(minimum+index/scale,index%scale,places),random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){String raw=read(q);if(raw==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");String input=Expression.normalize(answers.get(0).trim());if(input.isEmpty()||input.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");if("fraction".equals(q.answerFormat)&&!input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if(!input.matches("[+-]?\\d+(?:\\.\\d+)?(?:/[+-]?\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"마지막 답은 수로 입력");try{if(!Expression.number(input).equals(Expression.number(raw)))return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");if("reduced".equals(q.kind)){if(input.contains("."))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if(input.contains("/")){String[] pair=input.split("/");if(!new BigInteger(pair[0]).gcd(new BigInteger(pair[1])).equals(BigInteger.ONE))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"약분 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}catch(RuntimeException ex){return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"수 입력 확인 필요");}}
 public static int errorPart(Question q,String input){String raw=read(q);if(raw==null||input==null||input.length()>120||FractionInput.invalidPart(input)!=0)return 0;String[] pair=FractionInput.parts(input);BigInteger n=new BigInteger(pair[0]),d=new BigInteger(pair[1]);Rational value=Expression.number(raw);if(n.multiply(value.d).equals(value.n.multiply(d)))return 0;int places=raw.length()-raw.indexOf('.')-1;BigInteger den=BigInteger.TEN.pow(places),num=new BigDecimal(raw).movePointRight(places).toBigIntegerExact();if(d.equals(den)||d.equals(value.d))return 1;if(n.equals(num)||n.equals(value.n))return 2;return 0;}
}
